# F24's page: the hooks KiroCrew 0.7.1/0.7.2's chat page offers its drawers
# at phone width (App-e17PGpKz.js), and nothing else. The chat root carries
# data-owns-swipe="left right"; the header's "Toggle sessions" button opens
# the sessions drawer, which shows a [data-testid=sessions-backdrop]; a
# window "toggle-activity-panel" event toggles the activity drawer, whose
# header has a "Close panel" button. "left"/"right" are each drawer's state,
# "events" counts the toggle events.
PANES = """<!doctype html><meta charset=utf-8>
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>panes</title>
<style>body{margin:0;font:20px -apple-system}#l,#r,#b{display:none;position:fixed;top:0;bottom:0}
#l{left:0;width:70%;background:#cde;z-index:2}#r{left:0;right:0;background:#edc;z-index:1}
#b{left:0;right:0;background:rgba(0,0,0,.3);z-index:1}</style>
<div data-owns-swipe="left right" style="height:100vh">
<button aria-label="Toggle sessions" id=t style="font-size:20px;margin:60px 20px">=</button>
<p style="margin:20px">Chat</p></div>
<div id=l>Sessions</div>
<div id=r><button aria-label="Close panel" id=c style="font-size:20px;margin:60px 20px">x</button>Activity</div>
<script>
var r = {page: "panes", doc: Math.random().toString(36).slice(2),
         left: "closed", right: "closed", events: 0};
function report() {
  fetch("/__report", {method: "POST", body: JSON.stringify(r)}).catch(function () {});
}
function show(id, on) { document.getElementById(id).style.display = on ? "block" : "none"; }
function left(open) {
  r.left = open ? "open" : "closed"; show("l", open);
  // Like the real page: the backdrop exists only while the drawer does.
  var b = document.getElementById("b");
  if (open && !b) {
    b = document.createElement("div"); b.id = "b"; b.dataset.testid = "sessions-backdrop";
    document.body.appendChild(b);
  } else if (!open && b) { b.remove(); }
  if (b) { b.style.display = "block"; b.onclick = function () { left(false); }; }
  report();
}
function right(open) { r.right = open ? "open" : "closed"; show("r", open); report(); }
document.getElementById("t").addEventListener("click", function () { left(r.left !== "open"); });
document.getElementById("c").addEventListener("click", function () { right(false); });
window.addEventListener("toggle-activity-panel", function () {
  r.events++; right(r.right !== "open");
});
report();
setInterval(report, 1000);
</script>"""


def speak_wav():
    """0.3 s of 440 Hz, 16-bit mono PCM: what SPEAK's synthesize() fetches."""
    rate, n = 22050, 6615
    pcm = b"".join(struct.pack("<h", int(8000 * math.sin(2 * math.pi * 440 * i / rate)))
                   for i in range(n))
    return (b"RIFF" + struct.pack("<I", 36 + len(pcm)) + b"WAVEfmt "
            + struct.pack("<IHHIIHH", 16, 1, 1, rate, rate * 2, 2, 16)
            + b"data" + struct.pack("<I", len(pcm)) + pcm)


# What /__mode?root= accepts: the page, the probes, F6's page, F17's,
# F23's, issue #10's and F24's. "single", "handoff*", "voice", "speak" and
# "panes" are not PROBEs: they report to /__report, not /__inset-report.
ROOTS = ("page",) + PROBES + ("single",) + tuple(HANDOFF_ROOTS) + ("voice", "speak", "panes")
    }

    /// F23 T2 + T3. The dashboard's main frame gets the mic on the gateway's
    /// origin without a WebKit prompt; the camera, and the mic from a srcdoc
    /// frame (the widget shape, which inherits the gateway's origin), do not.
    /// A frame from another origin cannot load at all under F6's rules, so
    /// the other-origin case is T0's (scripts/test-media-capture-policy.swift).
    func testTheDashboardGetsTheMicAndNothingElseDoes() async throws {
        let report = try await voiceRun { r in
            ["mic", "camera", "frame_mic"].allSatisfy { r[$0] as? String != "pending" }
        }
        XCTAssertEqual(report["mic"] as? String, "granted", "the main frame's mic request: \(report)")
        XCTAssertEqual(report["camera"] as? String, "NotAllowedError", "the camera is never granted: \(report)")
        XCTAssertEqual(report["frame_mic"] as? String, "NotAllowedError",
                       "a subframe never gets the mic, even on the gateway's origin: \(report)")
    }

    /// F23 T4. KiroCrew's streaming STT socket, /api/ws/stt, carries a binary
    /// frame to the gateway and a transcript back, over the same relay as
    /// /ws: F6 rule 4 allows it and the proxy journal shows the gateway.
    func testTheSpeechSocketReachesTheGatewayThroughTheProxy() async throws {
        let report = try await voiceRun { $0["stt"] as? String != "pending" }
        XCTAssertEqual(report["stt"] as? String, "reply:final", "the page's STT round trip: \(report)")
        let frames = try await dashboardState()["stt_frames"] as? Int ?? 0
        XCTAssertGreaterThanOrEqual(frames, 1, "the gateway received the audio frame")
        let connects = try await journalConnects()
        XCTAssertTrue(connects.contains { $0.host == "dash.tail-scale.ts.net" },
                      "the socket went through the proxy to the gateway; got \(connects)")
    }

    // MARK: - Issue #10: read-aloud

    /// The dashboard's read-aloud plays (`dashboard.py`'s SPEAK): a tap
    /// unlocks an AudioContext, the WAV arrives asynchronously, and the
    /// buffer source plays out to `ended`. Untapped (auto-speak's shape), it
    /// plays too: measured before the fix, WebKit's gesture gate does not
    /// hold Web Audio back here, so `mediaTypesRequiringUserActionForPlayback`
    /// stays at its default. What failed before the fix is the session type:
    /// `auto`, which WebKit turns into the ambient category the silent switch
    /// mutes. The simulator has no switch, so this checks the request, not
    /// the switch.
    func testReadAloudPlaysWithAndWithoutATap() async throws {
        try await Self.post("\(Self.dashboardControl)/__mode?root=speak")
        let app = launch(gateway: Self.gateway, suffix: Self.tailnetSuffix, peers: ["dash"])
        defer { app.terminate() }
        let auto = try await waitForReport(host: "dash.tail-scale.ts.net", timeout: 40) {
            $0["page"] as? String == "speak" && $0["auto"] as? String != "pending"
        }
        XCTAssertEqual(auto["auto"] as? String, "ended", "untapped playback: \(auto)")
        XCTAssertEqual(auto["audio_session"] as? String, "playback", "the page's audio session: \(auto)")

        let speak = app.webViews.buttons["Speak"]
        XCTAssertTrue(speak.waitForExistence(timeout: 10), "the Speak button")
        speak.tap()
        let tapped = try await waitForReport(host: "dash.tail-scale.ts.net", timeout: 20) {
            $0["page"] as? String == "speak" && $0["tap"] as? String != "pending"
        }
        XCTAssertEqual(tapped["tap"] as? String, "ended", "tapped playback: \(tapped)")
        XCTAssertEqual(tapped["tap_state"] as? String, "running", "the tapped context: \(tapped)")
    }

    // MARK: - F24: edge swipes open the dashboard's drawers

